import fs from "node:fs/promises";
import path from "node:path";

function isPlainObject(v) {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

function normalizeFiles(v) {
  return Array.isArray(v) ? v.filter(isPlainObject) : [];
}

function filesToDebug(files) {
  return files.map((f) => ({
    name: f.name,
    source: f.source,
    status: f.status,
    path: f.path,
    mime: f.mime,
    sizeBytes: f.sizeBytes,
  }));
}

function pickUploadFile(files) {
  const ready = files.filter(
    (f) => f.source === "upload" && f.status === "ready" && typeof f.path === "string" && f.path,
  );
  if (!ready.length) return null;

  const byExact = (name) => ready.find((f) => String(f.name || "").toLowerCase() === name);

  return (
    byExact("package.json") ||
    ready.find((f) => String(f.name || "").toLowerCase().endsWith("package.json")) ||
    ready.find((f) => String(f.name || "").toLowerCase().endsWith(".json")) ||
    ready[0]
  );
}

export default {
  async main(env, ctx) {
    const p = ctx?.params || {};

    // Keep these configurable in code only (UI hides params editor when schema is empty).
    const include = ["dependencies", "devDependencies"];
    const maxDeps = 300;

    const meta = {
      include,
      maxDeps,
      source: "upload",
      sourceFile: null,
      parsedAt: new Date().toISOString(),
      warnings: [],
      errors: [],
      debug: { filesSeen: [] },
    };

    const files = normalizeFiles(p.files ?? ctx?.input?.initialInput?.files ?? ctx?.input?.files);
    meta.debug.filesSeen = filesToDebug(files);

    const pick = pickUploadFile(files);
    if (!pick) {
      meta.errors.push("No package.json found: please upload package.json in Files");
      return { outputs: { deps: [], project: null, meta } };
    }

    const runDir = String(ctx?.files?.dirs?.runDir || "");
    const rel = String(pick?.path || "");
    if (!runDir || !rel) {
      meta.errors.push("Cannot locate runDir/path (Files metadata incomplete)");
      meta.sourceFile = { name: pick.name, source: pick.source, status: pick.status, path: pick.path };
      return { outputs: { deps: [], project: null, meta } };
    }

    meta.sourceFile = { name: pick.name, source: pick.source, status: pick.status, path: rel };

    let obj = null;
    try {
      const txt = await fs.readFile(path.join(runDir, rel), "utf8");
      obj = JSON.parse(String(txt));
    } catch (e) {
      meta.errors.push(`Failed to read/parse file: ${e instanceof Error ? e.message : String(e)}`);
      return { outputs: { deps: [], project: null, meta } };
    }

    if (!isPlainObject(obj)) {
      meta.errors.push("package.json parse result is not an object");
      return { outputs: { deps: [], project: null, meta } };
    }

    const project = {
      name: typeof obj?.name === "string" ? obj.name : null,
      version: typeof obj?.version === "string" ? obj.version : null,
    };

    const sections = {
      dependencies: obj?.dependencies && typeof obj.dependencies === "object" ? obj.dependencies : {},
      devDependencies: obj?.devDependencies && typeof obj.devDependencies === "object" ? obj.devDependencies : {},
      peerDependencies: obj?.peerDependencies && typeof obj.peerDependencies === "object" ? obj.peerDependencies : {},
      optionalDependencies: obj?.optionalDependencies && typeof obj.optionalDependencies === "object" ? obj.optionalDependencies : {},
    };

    const picked = [];
    for (const sectionName of include) {
      const sec = sections[sectionName];
      if (!sec || typeof sec !== "object") continue;
      for (const [name, range] of Object.entries(sec)) {
        if (typeof name !== "string") continue;
        if (typeof range !== "string") continue;
        picked.push({ name, range, section: sectionName });
      }
    }

    if (picked.length > maxDeps) meta.warnings.push(`Too many dependencies (${picked.length}), truncated to ${maxDeps}`);

    const seen = new Set();
    const deps = [];
    for (const d of picked) {
      if (seen.has(d.name)) continue;
      seen.add(d.name);
      deps.push(d);
      if (deps.length >= maxDeps) break;
    }

    return {
      outputs: {
        project,
        deps,
        meta,
      },
    };
  },
};

import semver from "semver";

function nowMs() {
  return Date.now();
}

async function withConcurrency(items, concurrency, worker) {
  const arr = Array.isArray(items) ? items : [];
  const c = Math.max(1, Math.min(20, Number(concurrency) || 5));
  const results = new Array(arr.length);
  let idx = 0;

  async function runOne() {
    while (true) {
      const i = idx++;
      if (i >= arr.length) return;
      results[i] = await worker(arr[i], i);
    }
  }

  const pool = new Array(Math.min(c, arr.length)).fill(0).map(() => runOne());
  await Promise.all(pool);
  return results;
}

async function fetchJsonWithTimeout(url, timeoutMs) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), Math.max(1, Number(timeoutMs) || 15000));
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; Maia-NPM-Outdated/1.0)",
        Accept: "application/json",
      },
    });
    return { res, json: res.ok ? await res.json() : null };
  } finally {
    clearTimeout(t);
  }
}

function pickLatestSatisfying(versions, range) {
  const list = Array.isArray(versions) ? versions.filter((v) => typeof v === "string") : [];
  // semver.maxSatisfying handles ordering.
  return semver.validRange(range) ? semver.maxSatisfying(list, range) : null;
}

export default {
  async main(env, ctx) {
    const p = ctx?.params || {};
    const upstream = ctx?.upstream || {};

    const parsed = upstream.parse_package_json?.data;
    const deps = Array.isArray(parsed?.outputs?.deps) ? parsed.outputs.deps : [];

    const timeoutMs = Number(p.timeoutMs ?? 15000) || 15000;
    const concurrency = Number(p.concurrency ?? 5) || 5;

    const meta = {
      timeoutMs,
      concurrency,
      checkedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    if (!deps.length) {
      meta.errors.push("No deps to check (upstream deps is empty)");
      return { outputs: { results: [], meta } };
    }

    const base = "https://registry.npmjs.org";

    const results = await withConcurrency(deps, concurrency, async (d) => {
      const name = String(d?.name || "");
      const range = String(d?.range || "");
      const section = String(d?.section || "");
      const started = nowMs();

      if (!name || !range) {
        return {
          name,
          range,
          section,
          ok: false,
          latest: null,
          latest_satisfying: null,
          status: 0,
          latency_ms: nowMs() - started,
          error: "missing_name_or_range",
        };
      }

      const url = `${base}/${encodeURIComponent(name)}`;

      try {
        const { res, json } = await fetchJsonWithTimeout(url, timeoutMs);
        const latency_ms = nowMs() - started;

        if (!res.ok || !json) {
          return {
            name,
            range,
            section,
            ok: false,
            latest: null,
            latest_satisfying: null,
            status: res.status,
            latency_ms,
            error: `HTTP ${res.status} ${res.statusText}`,
          };
        }

        const latest = typeof json?.["dist-tags"]?.latest === "string" ? json["dist-tags"].latest : null;
        const versions = json?.versions ? Object.keys(json.versions) : [];
        const latest_satisfying = pickLatestSatisfying(versions, range);

        const rangeValid = Boolean(semver.validRange(range));

        return {
          name,
          range,
          section,
          ok: true,
          range_valid: rangeValid,
          latest,
          latest_satisfying,
          status: res.status,
          latency_ms,
          error: null,
        };
      } catch (e) {
        const latency_ms = nowMs() - started;
        const msg = e instanceof Error ? e.message : String(e);
        const nameErr = e && typeof e === "object" && "name" in e ? String(e.name) : "";
        const isTimeout = nameErr === "AbortError";

        return {
          name,
          range,
          section,
          ok: false,
          latest: null,
          latest_satisfying: null,
          status: 0,
          latency_ms,
          error: isTimeout ? `timeout: ${msg}` : msg,
        };
      }
    });

    return {
      outputs: {
        results,
        meta,
      },
    };
  },
};

function escMd(s) {
  return String(s ?? "").replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
}

function compareStatus(a, b) {
  // Sort: errors first, then outdated, then ok.
  const aOk = Boolean(a?.ok);
  const bOk = Boolean(b?.ok);
  if (aOk !== bOk) return aOk ? 1 : -1;

  const aOut = Boolean(a?.latest) && Boolean(a?.latest_satisfying) && a.latest !== a.latest_satisfying;
  const bOut = Boolean(b?.latest) && Boolean(b?.latest_satisfying) && b.latest !== b.latest_satisfying;
  if (aOut !== bOut) return aOut ? -1 : 1;

  return String(a?.name || "").localeCompare(String(b?.name || ""));
}

export default {
  async main(env, ctx) {
    const upstream = ctx?.upstream || {};

    const parsed = upstream.parse_package_json?.data;
    const project = parsed?.outputs?.project || null;

    const fetched = upstream.fetch_registry?.data;
    const results = Array.isArray(fetched?.outputs?.results) ? fetched.outputs.results : [];

    const meta = {
      builtAt: new Date().toISOString(),
      wroteFile: false,
      fileName: "npm-outdated-report.md",
      filePath: null,
      errors: [],
      warnings: [],
    };

    const sorted = results.slice().sort(compareStatus);

    const total = sorted.length;
    const errorsCount = sorted.filter((r) => !r?.ok).length;
    const outdatedCount = sorted.filter((r) => r?.ok && r?.latest && r?.latest_satisfying && r.latest !== r.latest_satisfying).length;

    const lines = [];
    lines.push(`# npm Dependency Update Check Report`);
    lines.push("");
    lines.push(`- Generated at: ${new Date().toISOString()}`);
    if (project?.name) lines.push(`- Project:${project.name}${project.version ? `@${project.version}` : ""}`);
    lines.push(`- Total dependencies: ${total}`);
    lines.push(`- Query failures: ${errorsCount}`);
    lines.push(`- Upgradable (latest within range != latest in registry): ${outdatedCount}`);
    lines.push("");

    lines.push("## Details");
    lines.push("");
    lines.push("| # | Name | Section | Range | Latest (registry) | Latest satisfying range | Status | Error |");
    lines.push("| - | ---- | ------- | ----- | ---------------- | ----------------------- | ------ | ----- |");

    for (let i = 0; i < sorted.length; i++) {
      const r = sorted[i] || {};
      const name = escMd(r.name || "");
      const section = escMd(r.section || "");
      const range = escMd(r.range || "");
      const latest = escMd(r.latest || "-");
      const ls = escMd(r.latest_satisfying || "-");
      const status = r.ok ? (latest !== "-" && ls !== "-" && latest !== ls ? "OUTDATED" : "OK") : "ERROR";
      const err = escMd(r.error || "");

      lines.push(`| ${i + 1} | ${name} | ${section} | ${range} | ${latest} | ${ls} | ${status} | ${err} |`);
    }

    lines.push("");
    lines.push("## Interpretation");
    lines.push("");
    lines.push("- `Latest (registry)`: npm registry's dist-tag `latest`.");
    lines.push("- `Latest satisfying range`: the latest version that can be selected within your version range (Range).");
    lines.push("- If `Latest satisfying range` is lower than `Latest`: your current Range locks you to an older major version/range (you need to change the Range to upgrade to the latest).");

    const report_md = lines.join("\n");

    try {
      const r = await ctx.artifacts.writeText(meta.fileName, report_md, { kind: "file", summary: "npm outdated report (Markdown)" });
      meta.wroteFile = true;
      meta.filePath = r?.absPath || null;
    } catch (e) {
      meta.errors.push(`write/register artifact failed: ${e instanceof Error ? e.message : String(e)}`);
    }

    return {
      outputs: {
        report_md,
        file_name: meta.fileName,
        file_path: meta.filePath,
        wrote_file: meta.wroteFile,
        results: sorted,
        summary: { total, errors: errorsCount, outdated: outdatedCount },
        meta,
      },
    };
  },
};
